// presentation/slides-data.js - Payload mã hóa 11 Slides Thuyết trình (chỉ giải mã khi xác thực tương tác người thật)
(function (root) {
  const ENCRYPTED_PAYLOAD = "";
  root.__PRES_ENC_PAYLOAD__ = ENCRYPTED_PAYLOAD;

  function hydrate() {
    if (root.PresentationData) return root.PresentationData;
    if (!root.ContentShield || typeof root.ContentShield.decodePayload !== "function") {
      return null;
    }
    const data = root.ContentShield.decodePayload(ENCRYPTED_PAYLOAD);
    if (!data) return null;
    data.playlist = data.slides;
    root.PresentationData = data;
    return data;
  }

  root.hydratePresentationData = hydrate;
})(typeof window !== "undefined" ? window : globalThis);
